import { useEffect, useState, useCallback } from "react";
import { Trash2, Edit3, Save, X } from "lucide-react";
import { getApiBase } from "../api/base";
import useToast from "../hooks/useToast";
import useConfirm from "../hooks/useConfirm";
import { authFetch } from "../api/authFetch";
const API = getApiBase() + "/backend";

// Updated to single branch assignment (legacy multi-branch support removed)
const AdminUsers = () => {
  const toast = useToast();
  const confirm = useConfirm();
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [creating, setCreating] = useState(false);
  const [form, setForm] = useState({
    username: "",
    email: "",
    password: "",
    branch: "", // single branch id
    role: "employee", // allow admin creation here only
  });
  const [branches, setBranches] = useState([]);
  const [savingBranchUserId, setSavingBranchUserId] = useState(null); // user id currently updating branch
  const [editUserId, setEditUserId] = useState(null);
  const [editForm, setEditForm] = useState({
    username: "",
    email: "",
    role: "employee",
    password: "",
  });
  const [role, setRole] = useState(null);
  const [pharmacies, setPharmacies] = useState([]);
  const [pharmacyId, setPharmacyId] = useState("");

  const load = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const qs =
        role === "super_admin" && pharmacyId ? `?pharmacyId=${pharmacyId}` : "";
      const res = await authFetch(`${API}/user${qs}`);
      const data = await res.json();
      if (res.ok && data.success) setUsers(data.users || []);
      else setError(data.message || "Failed");
    } catch {
      setError("Network error");
    } finally {
      setLoading(false);
    }
  }, [role, pharmacyId]);
  const loadBranches = useCallback(async () => {
    try {
      if (role === "super_admin" && pharmacyId) {
        const res = await authFetch(
          `${API}/superadmin/pharmacies/${pharmacyId}/branches`
        );
        const data = await res.json();
        if (res.ok && data.success && Array.isArray(data.branches))
          setBranches(data.branches);
      } else {
        const res = await authFetch(`${API}/branch`);
        const data = await res.json();
        if (data.success && Array.isArray(data.branches))
          setBranches(data.branches);
      }
    } catch {
      /* ignore */
    }
  }, [role, pharmacyId]);

  useEffect(() => {
    setRole(localStorage.getItem("role"));
  }, []);
  // load pharmacies for super_admin
  useEffect(() => {
    const fetchPharmacies = async () => {
      if (role !== "super_admin") return;
      try {
        const res = await authFetch(`${API}/superadmin/pharmacies`);
        const data = await res.json();
        if (res.ok && data.success && Array.isArray(data.pharmacies)) {
          setPharmacies(data.pharmacies);
          if (!pharmacyId && data.pharmacies[0]?._id)
            setPharmacyId(data.pharmacies[0]._id);
        }
      } catch {
        /* ignore */
      }
    };
    fetchPharmacies();
  }, [role, pharmacyId, load, loadBranches]);
  // Load users/branches when scope changes
  useEffect(() => {
    load();
    loadBranches();
  }, [role, pharmacyId, load, loadBranches]);

  const handleChange = (e) =>
    setForm({ ...form, [e.target.name]: e.target.value });

  const create = async (e) => {
    e.preventDefault();
    setCreating(true);
    setError("");
    try {
      const payload = {
        username: form.username,
        email: form.email,
        password: form.password,
        branch: form.branch || undefined,
        role: form.role || "employee",
      };
      // For super admin creating users within a selected pharmacy, prefer the dedicated endpoint
      let res;
      if (role === "super_admin" && pharmacyId) {
        res = await authFetch(
          `${API}/superadmin/pharmacies/${pharmacyId}/users`,
          {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload),
          }
        );
      } else {
        res = await authFetch(`${API}/user`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        });
      }
      const data = await res.json();
      if (res.ok && data.success) {
        setForm({
          username: "",
          email: "",
          password: "",
          branch: "",
          role: "employee",
        });
        load();
        toast.success("User created");
      } else {
        const msg = data.message || "Create failed";
        setError(msg);
        toast.error(msg);
      }
    } catch {
      setError("Network error");
      toast.error("Network error");
    } finally {
      setCreating(false);
    }
  };
  const assignBranch = async (user, branchId) => {
    // clicking assigned branch again will unassign
    const nextBranch =
      user.branch && (user.branch._id || user.branch) === branchId
        ? null
        : branchId;
    setSavingBranchUserId(user._id);
    try {
      const res = await authFetch(`${API}/user/${user._id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ branch: nextBranch || undefined }),
      });
      const data = await res.json();
      if (res.ok && data.success) {
        setUsers((us) => us.map((u) => (u._id === user._id ? data.user : u)));
        toast.success("Branch updated");
      } else {
        toast.error(data.message || "Update failed");
      }
    } catch {
      toast.error("Network error");
    } finally {
      setSavingBranchUserId(null);
    }
  };

  const removeUser = async (id) => {
    const ok = await confirm({
      title: "Delete user?",
      message: "This will remove the user permanently.",
      confirmText: "Delete",
      tone: "danger",
    });
    if (!ok) return;
    try {
      const res = await authFetch(`${API}/user/${id}`, {
        method: "DELETE",
      });
      const data = await res.json();
      if (res.ok && data.success) {
        load();
        toast.success("User deleted");
      } else {
        const msg = data.message || "Delete failed";
        setError(msg);
        toast.error(msg);
      }
    } catch {
      setError("Network error");
      toast.error("Network error");
    }
  };

  const startEdit = (u) => {
    setEditUserId(u._id);
    setEditForm({
      username: u.username,
      email: u.email,
      role: u.role,
      password: "",
    });
  };
  const cancelEdit = () => {
    setEditUserId(null);
    setEditForm({ username: "", email: "", role: "employee", password: "" });
  };
  const saveEdit = async (u) => {
    const payload = {
      username: editForm.username,
      email: editForm.email,
      role: editForm.role,
    };
    if (editForm.password.trim()) payload.password = editForm.password.trim();
    try {
      const res = await authFetch(`${API}/user/${u._id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const data = await res.json();
      if (res.ok && data.success) {
        setUsers((us) => us.map((x) => (x._id === u._id ? data.user : x)));
        cancelEdit();
        toast.success("User updated");
      } else {
        toast.error(data.message || "Update failed");
      }
    } catch {
      toast.error("Network error");
    }
  };

  return (
    <div className="space-y-8">
      <div className="flex items-center justify-between flex-wrap gap-4">
        <h1 className="text-2xl font-bold">Users</h1>
        {role === "super_admin" && (
          <div className="flex items-center gap-2">
            <span className="text-xs text-white/70">Pharmacy</span>
            <select
              value={pharmacyId}
              onChange={(e) => setPharmacyId(e.target.value)}
              className="px-2 py-1.5 rounded bg-white/80 text-gray-800"
            >
              {pharmacies.map((p) => (
                <option key={p._id} value={p._id}>
                  {p.name}
                </option>
              ))}
            </select>
          </div>
        )}
        <button
          onClick={load}
          className="px-4 py-2 rounded bg-white/10 hover:bg-white/20 text-sm"
        >
          Refresh
        </button>
      </div>
      <div className="bg-white/10 rounded-xl p-6 border border-white/10 backdrop-blur overflow-x-auto">
        <h2 className="font-semibold mb-4 tracking-wide text-sm uppercase text-white/70">
          All Users
        </h2>
        <form
          onSubmit={create}
          className="mb-6 grid md:grid-cols-6 gap-3 text-xs md:text-sm"
        >
          <input
            name="username"
            value={form.username}
            onChange={handleChange}
            placeholder="Username"
            required
            className="px-2 py-1.5 rounded bg-white/80 text-gray-800"
          />
          <input
            name="email"
            type="email"
            value={form.email}
            onChange={handleChange}
            placeholder="Email"
            required
            className="px-2 py-1.5 rounded bg-white/80 text-gray-800"
          />
          <input
            name="password"
            type="password"
            value={form.password}
            onChange={handleChange}
            placeholder="Password"
            required
            className="px-2 py-1.5 rounded bg-white/80 text-gray-800"
          />
          <div className="flex flex-wrap gap-1 items-center max-h-20 overflow-auto p-1 bg-white/10 rounded border border-white/10">
            {branches.map((b) => {
              const selected = form.branch === b._id;
              return (
                <button
                  type="button"
                  key={b._id}
                  onClick={() =>
                    setForm((f) => ({ ...f, branch: selected ? "" : b._id }))
                  }
                  className={`px-2 py-1 rounded text-[10px] font-medium border transition ${
                    selected
                      ? "bg-[var(--brand)] border-[var(--brand)]"
                      : "bg-white/10 border-white/20 hover:bg-white/20"
                  }`}
                >
                  {b.name}
                </button>
              );
            })}
          </div>
          <select
            name="role"
            value={form.role}
            onChange={(e) => setForm((f) => ({ ...f, role: e.target.value }))}
            className="px-2 py-1.5 rounded bg-white/80 text-gray-800"
          >
            <option value="employee">Employee</option>
            <option value="admin">Admin</option>
          </select>
          <button
            disabled={creating}
            className="px-3 py-1.5 rounded bg-[var(--brand)] hover:bg-[var(--brand-hover)] text-white font-semibold disabled:opacity-60"
          >
            {creating
              ? "Saving..."
              : form.role === "admin"
              ? "Add Admin"
              : "Add Employee"}
          </button>
        </form>
        {loading ? (
          <div className="text-sm text-white/70">Loading...</div>
        ) : error ? (
          <div className="text-sm text-red-300">{error}</div>
        ) : users.length === 0 ? (
          <div className="text-sm text-white/60">No users</div>
        ) : (
          <table className="w-full text-xs md:text-sm">
            <thead>
              <tr className="text-left text-white/70 bg-white/5">
                <th className="py-2 pr-3">Username</th>
                <th className="py-2 pr-3">Email</th>
                <th className="py-2 pr-3">Role</th>
                <th className="py-2 pr-3">Branch</th>
                <th className="py-2 pr-3">Joined</th>
                <th className="py-2 pr-3">Actions</th>
              </tr>
            </thead>
            <tbody>
              {users.map((u) => (
                <tr
                  key={u._id}
                  className="border-t border-white/5 hover:bg-white/5"
                >
                  <td className="py-1.5 pr-3 font-medium text-white/90">
                    {editUserId === u._id ? (
                      <input
                        value={editForm.username}
                        onChange={(e) =>
                          setEditForm((f) => ({
                            ...f,
                            username: e.target.value,
                          }))
                        }
                        className="px-2 py-1 rounded bg-white/80 text-gray-800 w-32"
                      />
                    ) : (
                      u.username
                    )}
                  </td>
                  <td className="py-1.5 pr-3 text-white/70">
                    {editUserId === u._id ? (
                      <input
                        value={editForm.email}
                        onChange={(e) =>
                          setEditForm((f) => ({ ...f, email: e.target.value }))
                        }
                        className="px-2 py-1 rounded bg-white/80 text-gray-800 w-40"
                      />
                    ) : (
                      u.email
                    )}
                  </td>
                  <td className="py-1.5 pr-3 text-white/70">
                    {editUserId === u._id ? (
                      <select
                        value={editForm.role}
                        onChange={(e) =>
                          setEditForm((f) => ({ ...f, role: e.target.value }))
                        }
                        className="px-2 py-1 rounded bg-white/80 text-gray-800"
                      >
                        <option value="employee">Employee</option>
                        <option value="admin">Admin</option>
                      </select>
                    ) : (
                      u.role
                    )}
                  </td>
                  <td className="py-1.5 pr-3 text-white/70">
                    <div className="flex flex-wrap gap-1 max-w-[180px]">
                      {branches.map((b) => {
                        const assigned =
                          u.branch && (u.branch._id || u.branch) === b._id;
                        return (
                          <button
                            key={b._id}
                            disabled={savingBranchUserId === u._id}
                            onClick={() => assignBranch(u, b._id)}
                            className={`px-2 py-0.5 rounded text-[10px] border transition ${
                              assigned
                                ? "bg-[var(--brand)] border-[var(--brand)] text-white"
                                : "bg-white/10 border-white/20 text-white/70 hover:bg-white/20"
                            } ${
                              savingBranchUserId === u._id ? "opacity-50" : ""
                            }`}
                            title={
                              assigned ? "Unassign branch" : "Assign branch"
                            }
                            type="button"
                          >
                            {b.name}
                          </button>
                        );
                      })}
                      {u.branch &&
                        !branches.some(
                          (b) => b._id === (u.branch._id || u.branch)
                        ) && (
                          <span className="text-[10px] px-2 py-0.5 rounded bg-amber-500/20 border border-amber-400/30 text-amber-300">
                            Unknown
                          </span>
                        )}
                    </div>
                  </td>
                  <td className="py-1.5 pr-3 text-white/70">
                    {new Date(u.createdAt).toLocaleDateString()}
                  </td>
                  <td className="py-1.5 pr-3 text-white/70">
                    <div className="flex items-center gap-1">
                      {editUserId === u._id ? (
                        <>
                          <button
                            onClick={() => saveEdit(u)}
                            className="w-8 h-8 inline-flex items-center justify-center rounded-xl bg-green-500/20 border border-green-400/30 hover:bg-green-500/30"
                            title="Save"
                            type="button"
                          >
                            <Save className="w-4 h-4 text-green-300" />
                          </button>
                          <button
                            onClick={cancelEdit}
                            className="w-8 h-8 inline-flex items-center justify-center rounded-xl bg-white/10 border border-white/10 hover:bg-white/20"
                            title="Cancel"
                            type="button"
                          >
                            <X className="w-4 h-4 text-white/70" />
                          </button>
                          <input
                            type="password"
                            placeholder="New password"
                            value={editForm.password}
                            onChange={(e) =>
                              setEditForm((f) => ({
                                ...f,
                                password: e.target.value,
                              }))
                            }
                            className="ml-2 px-2 py-1 rounded bg-white/80 text-gray-800 text-xs"
                          />
                        </>
                      ) : (
                        <>
                          <button
                            onClick={() => startEdit(u)}
                            className="w-8 h-8 inline-flex items-center justify-center rounded-xl bg-white/10 border border-white/10 backdrop-blur-sm hover:bg-white/20 hover:border-white/20"
                            title="Edit User"
                            type="button"
                          >
                            <Edit3 className="w-4 h-4 text-white/70" />
                          </button>
                          {u.role !== "admin" && (
                            <button
                              onClick={() => removeUser(u._id)}
                              className="w-8 h-8 inline-flex items-center justify-center rounded-xl bg-white/10 border border-white/10 backdrop-blur-sm hover:bg-white/20 hover:border-white/20"
                              title="Delete User"
                              type="button"
                            >
                              <Trash2 className="w-4 h-4 text-white/60" />
                            </button>
                          )}
                        </>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default AdminUsers;
